	const params = new URLSearchParams($page.url.searchParams);

	if (!value || value === 'all') {
		params.delete(key);
	} else {
		params.set(key, value);
	}

	const query = params.toString();
	const nextUrl = query ? `${base}/triage?${query}` : `${base}/triage`;
